package com.bobbuy.livecart;

import com.bobbuy.model.*;import com.bobbuy.repository.*;import com.bobbuy.security.*;import com.bobbuy.service.ProductSaleService;
import java.math.*;import java.sql.ResultSet;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import static com.bobbuy.livecart.LiveCartModels.*;

@Service
public class LiveCartService {
 private final JdbcClient db; private final UserRepository users; private final ProductRepository products; private final ProductSaleService sales;
 public LiveCartService(JdbcClient db,UserRepository users,ProductRepository products,ProductSaleService sales){this.db=db;this.users=users;this.products=products;this.sales=sales;}
 private long customer(Authentication a){if(a==null||!a.isAuthenticated())throw new LiveCartException(401,"CART_UNAUTHENTICATED");if(!(a.getPrincipal() instanceof BobbuyAuthenticatedUser p)||p.id()==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_CUSTOMER")))throw LiveCartException.forbidden();return p.id();}
 private long merchant(){Long id=MerchantScope.current();if(id==null)throw LiveCartException.forbidden();return id;}
 private void lock(long cart){db.sql("select id from bb_live_cart where id=? for update").param(cart).query(Long.class).optional().orElseThrow(LiveCartException::forbidden);}
 private void scope(long cart,long actor,boolean customer){boolean ok=db.sql("select count(*) from bb_live_cart where id=? and "+(customer?"customer_id":"merchant_id")+"=?").param(cart).param(actor).query(Integer.class).single()>0;if(!ok)throw LiveCartException.forbidden();}
 private void version(long cart,long expected){long actual=db.sql("select version from bb_live_cart where id=?").param(cart).query(Long.class).single();if(actual!=expected)throw LiveCartException.conflict("CART_VERSION_CONFLICT");}
 private long bump(long cart){return db.sql("update bb_live_cart set version=version+1,updated_at=now(),last_activity_at=now() where id=? returning version").param(cart).query(Long.class).single();}
 private void event(long cart,Long line,long actor,String role,String action,Integer bq,Integer aq,BigDecimal bp,BigDecimal ap,String note){db.sql("insert into bb_live_cart_event(cart_id,line_id,actor_id,actor_role,action,before_quantity,after_quantity,before_unit_price,after_unit_price,note) values(?,?,?,?,?,?,?,?,?,?)").params(cart,line,actor,role,action,bq,aq,bp,ap,note).update();}
 private Line map(ResultSet r,int n)throws java.sql.SQLException{return new Line(r.getLong("id"),r.getString("product_id"),r.getInt("quantity"),r.getBigDecimal("unit_price"),r.getString("currency"),r.getString("price_source"),r.getObject("ready_at")!=null,r.getBoolean("visible_to_customer"),(Long)r.getObject("settlement_id"),r.getLong("version"),r.getObject("ready_quantity")!=null&&r.getInt("ready_quantity")!=r.getInt("quantity"));}
 private List<Line> lines(long cart,boolean customer){String filter=customer?" and visible_to_customer=true":"";return db.sql("select * from bb_live_cart_line where cart_id=?"+filter+" order by id").param(cart).query(this::map).list();}
 private Total total(List<Line> lines){int items=0,ul=0,ui=0;BigDecimal amount=BigDecimal.ZERO;String currency=null;for(Line l:lines){items+=l.quantity();if(l.unitPrice()==null){ul++;ui+=l.quantity();}else{amount=amount.add(l.unitPrice().multiply(BigDecimal.valueOf(l.quantity())));currency=currency==null?l.currency():currency;}}return new Total(lines.size(),items,amount,ul,ui,currency);}
 private Cart view(long id,boolean customer){var all=lines(id,customer);var open=all.stream().filter(x->x.settlementId()==null).toList();var settled=all.stream().filter(x->x.settlementId()!=null).toList();var head=db.sql("select c.*,u.name,u.phone,u.email,u.email_verified_at from bb_live_cart c join bb_user u on u.id=c.customer_id where c.id=?").param(id).query((r,n)->new Object[]{r.getLong("customer_id"),r.getLong("merchant_id"),r.getLong("version"),r.getString("name"),r.getString("phone"),r.getString("email"),r.getObject("email_verified_at")!=null,r.getTimestamp("last_activity_at").toInstant()}).single();
  var settlements=db.sql("select * from bb_live_cart_settlement where cart_id=? order by settled_at desc").param(id).query((r,n)->{long sid=r.getLong("id");var sl=settled.stream().filter(x->Objects.equals(x.settlementId(),sid)).toList();return new Settlement(sid,r.getTimestamp("settled_at").toInstant(),r.getTimestamp("reopened_at")==null?null:r.getTimestamp("reopened_at").toInstant(),total(sl),sl);}).list();
  return new Cart(id,(long)head[0],(long)head[1],(long)head[2],(String)head[3],(String)head[4],(String)head[5],(boolean)head[6],open,settlements,total(open),total(settled),(Instant)head[7]);}
 public List<Cart> customerCarts(Authentication a){long uid=customer(a);return db.sql("select id from bb_live_cart where customer_id=? order by last_activity_at desc").param(uid).query(Long.class).list().stream().map(id->view(id,true)).toList();}
 public CartList merchantCarts(String status,long since){long owner=merchant();var ids=db.sql("select c.id from bb_live_cart c where merchant_id=? and version>? and (?='ALL' or (?='OPEN' and exists(select 1 from bb_live_cart_line l where l.cart_id=c.id and l.settlement_id is null)) or (?='SETTLED' and not exists(select 1 from bb_live_cart_line l where l.cart_id=c.id and l.settlement_id is null))) order by last_activity_at desc").params(owner,since,status,status,status).query(Long.class).list();long max=db.sql("select coalesce(max(version),0) from bb_live_cart where merchant_id=?").param(owner).query(Long.class).single();return new CartList(ids.stream().map(id->view(id,false)).toList(),max);}
 public Cart customerCart(long id,Authentication a){long uid=customer(a);scope(id,uid,true);return view(id,true);} public Cart merchantCart(long id){scope(id,merchant(),false);return view(id,false);}
 @Transactional public Cart addCustomer(AddLine in,Authentication a){long uid=customer(a);int q=in.quantity()==null?1:in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");Product p=products.findById(in.productId()).filter(x->x.publiclyCartEnabled()).orElseThrow(()->LiveCartException.invalid("CART_PRODUCT_UNAVAILABLE"));long owner=Objects.requireNonNull(p.getMerchantId());db.sql("insert into bb_live_cart(customer_id,merchant_id) values(?,?) on conflict(customer_id,merchant_id) do nothing").params(uid,owner).update();long cart=db.sql("select id from bb_live_cart where customer_id=? and merchant_id=?").params(uid,owner).query(Long.class).single();lock(cart);var existing=db.sql("select * from bb_live_cart_line where cart_id=? and product_id=? and settlement_id is null and visible_to_customer and added_by='CUSTOMER' for update").params(cart,p.getId()).query(this::map).optional();
  if(existing.isPresent()){Line x=existing.get();if(x.quantity()+q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");db.sql("update bb_live_cart_line set quantity=quantity+?,version=version+1,updated_at=now() where id=?").params(q,x.id()).update();event(cart,x.id(),uid,"CUSTOMER","QUANTITY_CHANGED",x.quantity(),x.quantity()+q,x.unitPrice(),x.unitPrice(),null);}else{int count=db.sql("select count(*) from bb_live_cart_line where cart_id=? and settlement_id is null").param(cart).query(Integer.class).single();if(count>=50)throw LiveCartException.invalid("CART_LINE_LIMIT");var quote=sales.quote(p);BigDecimal price=quote.map(ProductSaleService.Quote::amount).orElse(null);String cur=quote.map(ProductSaleService.Quote::currency).orElse("JPY");long line=db.sql("insert into bb_live_cart_line(cart_id,product_id,quantity,unit_price,currency,price_source,added_by) values(?,?,?,?,?,'REFERENCE','CUSTOMER') returning id").params(cart,p.getId(),q,price,cur).query(Long.class).single();event(cart,line,uid,"CUSTOMER","ADDED",null,q,null,price,null);}bump(cart);return view(cart,true);}
 public Cart customerChangeByLine(long line,ChangeLine in,Authentication a,boolean delete){long uid=customer(a);long cart=db.sql("select c.id from bb_live_cart c join bb_live_cart_line l on l.cart_id=c.id where l.id=? and c.customer_id=?").params(line,uid).query(Long.class).optional().orElseThrow(LiveCartException::forbidden);return customerChange(cart,line,in,a,delete);}
 @Transactional public Cart customerChange(long cart,long line,ChangeLine in,Authentication a,boolean delete){long uid=customer(a);lock(cart);scope(cart,uid,true);version(cart,in.expectedVersion());Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.settlementId()!=null)throw LiveCartException.conflict("CART_LINE_SETTLED");if(!old.visibleToCustomer())throw LiveCartException.forbidden();if(delete){db.sql("delete from bb_live_cart_line where id=?").param(line).update();event(cart,line,uid,"CUSTOMER","DELETED",old.quantity(),null,old.unitPrice(),null,null);}else{if(in.quantity()==null||in.quantity()<1||in.quantity()>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");db.sql("update bb_live_cart_line set quantity=?,version=version+1,updated_at=now() where id=?").params(in.quantity(),line).update();event(cart,line,uid,"CUSTOMER","QUANTITY_CHANGED",old.quantity(),in.quantity(),old.unitPrice(),old.unitPrice(),null);}bump(cart);return view(cart,true);}
 @Transactional public Cart merchantAdd(long cart,AddLine in){long actor=merchant();lock(cart);scope(cart,actor,false);int q=in.quantity()==null?1:in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");Product p=products.findById(in.productId()).filter(x->Objects.equals(actor,x.getMerchantId())).orElseThrow(()->LiveCartException.invalid("CART_PRODUCT_UNAVAILABLE"));if(db.sql("select count(*) from bb_live_cart_line where cart_id=? and settlement_id is null").param(cart).query(Integer.class).single()>=50)throw LiveCartException.invalid("CART_LINE_LIMIT");BigDecimal price=in.unitPrice();String currency="JPY";if(price==null){var quote=sales.quote(p);price=quote.map(ProductSaleService.Quote::amount).orElse(null);currency=quote.map(ProductSaleService.Quote::currency).orElse("JPY");}validatePrice(price,currency);boolean visible=!Boolean.TRUE.equals(in.hiddenFromCustomer());long line=db.sql("insert into bb_live_cart_line(cart_id,product_id,quantity,unit_price,currency,price_source,visible_to_customer,added_by) values(?,?,?,?,?,? ,?,'AGENT') returning id").params(cart,p.getId(),q,price,currency,in.unitPrice()==null?"REFERENCE":"AGENT",visible).query(Long.class).single();event(cart,line,actor,"AGENT","AGENT_ADDED",null,q,null,price,null);bump(cart);return view(cart,false);}
 private void validatePrice(BigDecimal p,String currency){if(p==null)return;int digits=java.util.Currency.getInstance(currency).getDefaultFractionDigits();if(p.signum()<0||p.stripTrailingZeros().scale()>digits)throw LiveCartException.invalid("CART_PRICE_INVALID");}
 @Transactional public Cart merchantChange(long cart,long line,ChangeLine in,boolean delete){long actor=merchant();lock(cart);scope(cart,actor,false);version(cart,in.expectedVersion());Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(delete){db.sql("delete from bb_live_cart_line where id=?").param(line).update();event(cart,line,actor,"AGENT","AGENT_DELETED",old.quantity(),null,old.unitPrice(),null,null);}else{int q=in.quantity()==null?old.quantity():in.quantity();if(q<1||q>99)throw LiveCartException.invalid("CART_QUANTITY_INVALID");BigDecimal price=in.unitPrice()==null?old.unitPrice():in.unitPrice();validatePrice(price,old.currency());boolean visible=in.hiddenFromCustomer()==null?old.visibleToCustomer():!in.hiddenFromCustomer();if(old.settlementId()!=null&&!visible)throw LiveCartException.conflict("CART_SETTLED_CANNOT_HIDE");String source=in.unitPrice()==null?old.priceSource():"AGENT";db.sql("update bb_live_cart_line set quantity=?,unit_price=?,price_source=?,visible_to_customer=?,version=version+1,updated_at=now() where id=?").params(q,price,source,visible,line).update();String action=!Objects.equals(old.unitPrice(),price)?"PRICE_CHANGED":old.visibleToCustomer()!=visible?(visible?"UNHIDDEN":"HIDDEN"):"QUANTITY_CHANGED";event(cart,line,actor,"AGENT",action,old.quantity(),q,old.unitPrice(),price,null);}bump(cart);return view(cart,false);}
 @Transactional public Cart ready(long cart,long line,boolean ready){long actor=merchant();lock(cart);scope(cart,actor,false);Line old=db.sql("select * from bb_live_cart_line where id=? and cart_id=? for update").params(line,cart).query(this::map).optional().orElseThrow(LiveCartException::forbidden);if(old.ready()==ready)return view(cart,false);if(ready)db.sql("update bb_live_cart_line set ready_by=?,ready_at=now(),ready_quantity=?,version=version+1 where id=?").params(actor,old.quantity(),line).update();else db.sql("update bb_live_cart_line set ready_by=null,ready_at=null,ready_quantity=null,version=version+1 where id=?").param(line).update();event(cart,line,actor,"AGENT",ready?"READY":"UNREADY",old.quantity(),old.quantity(),old.unitPrice(),old.unitPrice(),null);bump(cart);return view(cart,false);}
 private List<Line> selected(long cart,List<Long> ids,boolean requireOpen){if(ids==null||ids.isEmpty())throw LiveCartException.invalid("CART_SETTLEMENT_EMPTY");var result=db.sql("select * from bb_live_cart_line where cart_id=? and id in (select unnest(?::bigint[])) for update").params(cart,ids.toArray(Long[]::new)).query(this::map).list();if(result.size()!=new HashSet<>(ids).size()||(requireOpen&&result.stream().anyMatch(x->x.settlementId()!=null)))throw LiveCartException.invalid("CART_SETTLEMENT_LINES_INVALID");return result;}
 public Preview preview(long cart,List<Long> ids){long actor=merchant();scope(cart,actor,false);var all=lines(cart,false).stream().filter(x->x.settlementId()==null).toList();var set=new HashSet<>(ids);if(ids==null||ids.isEmpty()||all.stream().filter(x->set.contains(x.id())).count()!=set.size())throw LiveCartException.invalid("CART_SETTLEMENT_LINES_INVALID");return new Preview(total(all.stream().filter(x->set.contains(x.id())).toList()),total(all.stream().filter(x->!set.contains(x.id())).toList()));}
 @Transactional public Cart settle(long cart,SelectLines in){long actor=merchant();lock(cart);scope(cart,actor,false);version(cart,in.expectedVersion());var chosen=selected(cart,in.lineIds(),true);var totals=total(chosen);long settlement=db.sql("insert into bb_live_cart_settlement(cart_id,settled_by,line_count,item_count,amount,unpriced_item_count,currency) values(?,?,?,?,?,?,?) returning id").params(cart,actor,totals.lineCount(),totals.itemCount(),totals.amount(),totals.unpricedItemCount(),totals.currency()).query(Long.class).single();for(Line line:chosen){if(!line.visibleToCustomer()){db.sql("update bb_live_cart_line set visible_to_customer=true where id=?").param(line.id()).update();event(cart,line.id(),actor,"AGENT","AUTO_UNHIDDEN",line.quantity(),line.quantity(),line.unitPrice(),line.unitPrice(),null);}db.sql("update bb_live_cart_line set settlement_id=?,version=version+1,updated_at=now() where id=?").params(settlement,line.id()).update();}event(cart,null,actor,"AGENT","SETTLED",null,null,null,null,"settlement="+settlement+" lines="+in.lineIds());bump(cart);return view(cart,false);}
 @Transactional public Cart reopen(long cart,long sid,String note){long actor=merchant();if(note==null||note.isBlank()||note.length()>1000)throw LiveCartException.invalid("CART_REOPEN_NOTE_REQUIRED");lock(cart);scope(cart,actor,false);boolean reopened=db.sql("select reopened_at is not null from bb_live_cart_settlement where id=? and cart_id=? for update").params(sid,cart).query(Boolean.class).optional().orElseThrow(()->LiveCartException.invalid("CART_SETTLEMENT_INVALID"));if(reopened)return view(cart,false);db.sql("update bb_live_cart_settlement set reopened_by=?,reopened_at=now(),reopen_note=? where id=?").params(actor,note.trim(),sid).update();db.sql("update bb_live_cart_line set settlement_id=null,version=version+1,updated_at=now() where settlement_id=?").param(sid).update();event(cart,null,actor,"AGENT","REOPENED",null,null,null,null,"settlement="+sid+" "+note.trim());bump(cart);return view(cart,false);}
}
